import{_ as t}from"./chunks/rmlui.IQCB0h4b.js";import{_ as e,o as r,c as i,a2 as s}from"./chunks/framework.Ky-Ipuyb.js";const k=JSON.parse('{"title":"RmlUi 指南","description":"","frontmatter":{"lang":"zh-CN","sourcePath":"docs/rmlui/README.zh-CN.md"},"headers":[],"relativePath":"zh/rmlui/index.md","filePath":"zh/rmlui/index.md"}'),l={name:"zh/rmlui/index.md"};function h(d,a,n,o,m,p){return r(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="rmlui-指南" tabindex="-1">RmlUi 指南 <a class="header-anchor" href="#rmlui-指南" aria-label="Permalink to &quot;RmlUi 指南&quot;">​</a></h1><p><a class="library-brand" href="https://mikke89.github.io/RmlUiDoc/"><img src="'+t+`" width="246" height="84" alt="RmlUi"></a></p><p>使用 <code>sfml.js-rmlui</code> 在 SFML 窗口内构建文档式界面：RML 描述元素树，RCSS 控制外观，JavaScript 管理应用状态和事件处理。当前源码面向 RmlUi 6.3 和 SFML 3.1。</p><p>阅读前需了解 JavaScript 和 <a href="/zh/guide/window">SFML 窗口</a>。RmlUi 6.3 的语法类似 HTML/CSS，但没有嵌入浏览器。<a href="/zh/rmlui/data-models">原生数据模型</a>涵盖标量和回调绑定、递归记录及数组、自定义变量、共享数值存储和稀疏更新。下列指南介绍运行时、文档树、样式、渲染、输入、字体、脚本和资源所有权；<a href="/zh/reference/rmlui/" target="_self">API 参考</a>说明对应的 TypeScript 接口约定。</p><h2 id="什么是-rmlui" tabindex="-1">什么是 RmlUi <a class="header-anchor" href="#什么是-rmlui" aria-label="Permalink to &quot;什么是 RmlUi&quot;">​</a></h2><p><a href="https://github.com/mikke89/RmlUi" target="_blank" rel="noreferrer">RmlUi</a> 是一个采用类 HTML/CSS 文档语法的 C++ 界面库。它使用保留模式（Retained Mode）：加载 RML 后创建持久的元素树，用 RCSS 设置样式，再根据应用状态修改具体元素。RmlUi 负责布局和生成几何数据，本包通过 SFML 完成绘制。</p><p>它适合游戏菜单、HUD、背包窗口，以及希望把布局和视觉设计放在独立资源文件中的界面。RML、RCSS 和 Node.js 事件处理代码共同工作，运行时没有浏览器 DOM 或网页 JavaScript 环境。需要逐帧调用控件来组合工具界面时，可阅读 <a href="/zh/imgui/">ImGui 指南</a>。</p><p><a href="https://mikke89.github.io/RmlUiDoc/" target="_blank" rel="noreferrer">官方文档</a> · <a href="https://github.com/mikke89/RmlUi" target="_blank" rel="noreferrer">官方仓库</a></p><h2 id="学习路径" tabindex="-1">学习路径 <a class="header-anchor" href="#学习路径" aria-label="Permalink to &quot;学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>内容</th></tr></thead><tbody><tr><td><a href="/zh/rmlui/getting-started">快速开始</a></td><td>运行计数器，了解初始化、字体和帧顺序</td></tr><tr><td><a href="/zh/rmlui/rml-rcss">RML 与 RCSS 入门</a></td><td>编写标签、选择器和布局，连接点击事件，查阅官方语法</td></tr><tr><td><a href="/zh/rmlui/documents">文档与事件</a></td><td>加载 RML、修改元素、注册监听器与释放原生对象</td></tr><tr><td><a href="/zh/rmlui/debugger">原生 Debugger</a></td><td>在独立宿主中检查元素、日志与数据模型反射</td></tr><tr><td><a href="/zh/rmlui/vector-elements">SVG 与 Lottie</a></td><td>原生矢量元素、装饰器、动画帧和源文件</td></tr><tr><td><a href="/zh/rmlui/geometry-utilities">原生几何与卷积</a></td><td>批量生成网格，在共享 alpha 缓冲区上运行滤镜</td></tr><tr><td><a href="/zh/rmlui/rendering">渲染与 Retina</a></td><td>组合 SFML 与 RmlUi、适配高密度显示及了解效果支持</td></tr><tr><td><a href="/zh/rmlui/performance">共享存储与批处理</a></td><td>提交数值命令、批量自定义计算及预加载资源</td></tr><tr><td><a href="/zh/rmlui/api">API 指南</a></td><td>查找类型、默认值、返回值和生命周期契约</td></tr></tbody></table><p>指南和从源码生成的 API 参考均维护英文、简体中文、日文、韩文版本。</p><h2 id="运行示例" tabindex="-1">运行示例 <a class="header-anchor" href="#运行示例" aria-label="Permalink to &quot;运行示例&quot;">​</a></h2><p>在 monorepo 根目录执行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/bootstrap.cjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-rmlui/examples/demo.cjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-rmlui/examples/official.cjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> variables</span></span></code></pre></div><p><a href="/zh/examples/rmlui">示例目录</a>提供截图、操作说明和源码链接。计数器的 Increment 按钮可以点击计数；variables 页的任务按钮仅展示悬停样式。</p><h2 id="所有权边界" tabindex="-1">所有权边界 <a class="header-anchor" href="#所有权边界" aria-label="Permalink to &quot;所有权边界&quot;">​</a></h2><p>进程级运行时绑定一个 <code>RenderWindow</code>，归初始化它的 Node.js 环境和线程所有，管理上下文、文档、字体和渲染资源。元素包装器共享原生有效性。JS 引用会保活持有所有权的脱离树；已挂载节点的生命周期由原生父节点决定。销毁时自动释放监听器，访问失效包装器会抛出异常。关闭 SFML 窗口前关闭 RmlUi。文档延迟销毁和 Worker 限制见<a href="/zh/rmlui/documents#原生对象生命周期">原生对象生命周期</a>。</p>`,17)])])}const f=e(l,[["render",h]]);export{k as __pageData,f as default};
